/* BioBuzz Alliance Matrix | local-first FTC scouting workspace */
(() => {
'use strict';
const STORE_KEY='biobuzz-alliance-matrix-v1', MODEL_VERSION='BIOBUZZ TU05 · 15.10.2026';
const teamsSeed=[
['D-101','HiveLab','Алматы','Сильный HIVE'],['D-102','PetalWorks','Алматы','Сильный FLOWER'],['D-103','Pollen Drive','Астана','Сбалансированный'],['D-104','Nectar Motion','Алматы','Высокая автономия'],['D-105','Green Circuit','Шымкент','Стабильная парковка'],['D-106','Bloom Robotics','Астана','Сильный FLOWER'],['D-107','Cell Seekers','Караганда','Сильный HIVE'],['D-108','Orbit Orchard','Алматы','Сбалансированный'],['D-109','Honeycomb','Тараз','Высокая автономия'],['D-110','Field Notes','Астана','Стабильный робот'],['D-111','Garden State','Шымкент','Сильный FLOWER'],['D-112','Amber Bots','Караганда','Сбалансированный']];
const profiles=[[1,1,1.7,2.2,2,3,2,1,4,1,0],[1,0,.7,.7,1,7,3,2,2,1,0],[1,1,1,1.5,2,3,2,1,3,1,0],[1,1,1.4,1.5,1,4,2,1,2,1,1],[1,1,.5,.8,1,3,1,0,4,1,0],[1,0,.4,.8,1,7,4,2,1,1,0],[0,1,1.3,2.1,2,2,1,0,3,1,0],[1,1,1,1.3,2,4,2,1,3,1,0],[1,1,1.5,1.8,2,2,1,0,2,1,0],[1,1,.8,1,1,4,2,1,3,1,0],[1,0,.5,.9,1,6,3,2,1,1,0],[1,1,.9,1.2,2,3,2,1,3,1,0]];
const labels={overview:'Обзор',scouting:'Скаутинг',teams:'Команды',analysis:'Анализ альянса',draft:'Доска драфта',data:'Импорт и экспорт'};
let page='overview',searchTerm='',teamFilter='all',activeTeam=null,analysisSelection=['D-101','D-102','D-105','D-106'],simResult=null,toastTimer,officialView='',selectedEventName='';
const main=document.getElementById('main');
function rngSeed(seed){let x=seed>>>0;return()=>{x=(x*1664525+1013904223)>>>0;return x/4294967296;};}
function makeSeed(){const teams=teamsSeed.map(t=>({id:t[0],number:t[0],name:t[1],region:t[2],style:t[3],notes:''})),rand=rngSeed(20262027),records=[];teams.forEach((t,i)=>{const p=profiles[i];for(let m=1;m<=5;m++){const jit=a=>Math.round((rand()-.5)*a*2);records.push({id:`demo-${i}-${m}`,teamId:t.id,eventCode:'DEMO-ALMATY',eventName:'Демо-турнир · учебные данные',matchNo:m,date:`2026-10-${String(10+m).padStart(2,'0')}`,autoLeave:rand()<.88,autoPark:rand()<p[1]*.74,autoHiveTips:Math.max(0,Math.round(p[2]+jit(.65))),teleopHiveTips:Math.max(0,Math.round(p[3]+jit(.8))),cellItems:Math.max(0,Math.round(p[4]+jit(1))),flowerPlaced:Math.max(0,Math.round(p[5]+jit(2))),ownedFlowerItems:Math.max(0,Math.round(p[6]+jit(1))),bottomNectar:Math.max(0,Math.round(p[7]+jit(1))),gardenItems:Math.max(0,Math.round(p[8]+jit(2))),teleopPark:rand()<p[9]*.83,penalties:rand()<.1?p[10]:0,disabled:rand()<.035,confidence:rand()>.14?'high':'medium',scout:'Демо-сценарий',notes:''});}});return{version:1,meta:{demo:true,eventName:'Демо-турнир · учебные данные',eventCode:'DEMO-ALMATY',season:'2026-2027',updatedAt:new Date().toISOString()},teams,records,draft:{captain:'D-101',picked:[],removed:[]}};}
function load(){try{const x=JSON.parse(localStorage.getItem(STORE_KEY));if(x&&Array.isArray(x.teams)&&Array.isArray(x.records))return x;}catch(e){console.warn(e);}const x=makeSeed();localStorage.setItem(STORE_KEY,JSON.stringify(x));return x;}
let db=load();
function save(){db.meta.updatedAt=new Date().toISOString();localStorage.setItem(STORE_KEY,JSON.stringify(db));const x=document.getElementById('syncStatus');if(x)x.textContent='Сохранено локально';}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function num(v){const x=Number(v);return Number.isFinite(x)?x:0;} function clamp(x,a,b){return Math.max(a,Math.min(b,x));} function avg(a){return a.length?a.reduce((x,y)=>x+y,0)/a.length:0;} function sd(a){if(a.length<2)return a.length?Math.max(4,a[0]*.17):0;const m=avg(a);return Math.sqrt(avg(a.map(x=>(x-m)**2)));} function fmt(v,d=1){return Number(v||0).toFixed(d).replace('.',',');}
function team(id){return db.teams.find(x=>x.id===id);} function rows(id){return db.records.filter(x=>x.teamId===id&&(!db.meta.eventCode||x.eventCode===db.meta.eventCode));} function teamLabel(t){return t?`${t.number} · ${t.name}`:'Команда не выбрана';} function initials(t){return(t?.name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function breakdown(r){const auto=(r.autoLeave?3:0)+(r.autoPark?5:0)+num(r.autoHiveTips)*20;const hive=num(r.teleopHiveTips)*20+num(r.cellItems)*2;const flower=num(r.ownedFlowerItems)*2+num(r.bottomNectar)*5;const field=num(r.gardenItems)+(r.teleopPark?5:0);const foul=num(r.penalties)*5;return{auto,hive,flower,field,foul,total:Math.max(0,auto+hive+flower+field-foul)};}
function stats(t){if(!t)return null;const rs=rows(t.id),bs=rs.map(breakdown),values=bs.map(x=>x.total),auto=avg(bs.map(x=>x.auto)),hive=avg(bs.map(x=>x.hive)),flower=avg(bs.map(x=>x.flower)),mean=avg(values),spread=sd(values),count=rs.length;return{team:t,records:rs,count,mean,sd:spread,auto,hive,flower,field:avg(bs.map(x=>x.field)),autoTips:avg(rs.map(x=>x.autoHiveTips)),teleopTips:avg(rs.map(x=>x.teleopHiveTips)),flowerOwned:avg(rs.map(x=>x.ownedFlowerItems)),flowerPlaced:avg(rs.map(x=>x.flowerPlaced)),parkRate:count?rs.filter(x=>x.teleopPark).length/count:0,confidence:count>=8?'Высокая':count>=4?'Средняя':count?'Низкая':'Нет данных',consistency:clamp(100-spread/Math.max(25,mean||25)*100,15,98),profile:{auto:clamp(auto/30*100,0,100),hive:clamp(hive/60*100,0,100),flower:clamp(flower/35*100,0,100),reliability:clamp(count?100-Math.min(spread/Math.max(1,mean)*100,70):0,0,100)}};}
function allStats(){return db.teams.map(stats);} function priority(s){if(!s?.count)return'—';if(s.mean>=70&&s.consistency>=62)return'A';if(s.mean>=46)return'Б';return'В';}
function pairModel(x,y){const a=typeof x==='string'?stats(team(x)):x,b=typeof y==='string'?stats(team(y)):y;if(!a||!b)return null;const keys=['auto','hive','flower','reliability'],cover=avg(keys.map(k=>Math.max(a.profile[k],b.profile[k]))),complement=avg(keys.map(k=>Math.abs(a.profile[k]-b.profile[k]))),dataFactor=Math.min(1,(a.count+b.count)/12),stability=avg([a.consistency,b.consistency]),score=clamp(cover*.56+complement*.12+stability*.18+dataFactor*14,0,100),synergyPts=Math.round((score-50)*.12*10)/10;return{a,b,score,cover,complement,stability,mean:Math.max(0,a.mean+b.mean+synergyPts),sd:Math.sqrt(a.sd*a.sd+b.sd*b.sd+25)};}
function opt(t,selected=''){return`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(teamLabel(t))}</option>`;} function banner(){return db.meta.demo?`<div class="demo-banner"><span class="banner-mark">i</span><span><strong>Показаны учебные данные.</strong> Названия команд и матчи вымышлены. Импортируйте свои наблюдения или удалите демо-набор на странице «Импорт и экспорт».</span></div>`:'';}
function head(title,sub,actions=''){return`<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;} function kpi(label,value,foot,mark){return`<article class="kpi-card"><span class="kpi-label">${label}</span><span class="kpi-icon">${mark}</span><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></article>`;} function badge(x){return`<span class="grade ${x==='A'?'grade-a':x==='Б'?'grade-b':'grade-c'}">${esc(x)}</span>`;}
function avgChart(items){if(!items.length)return`<div class="chart-empty">Добавьте команды и скаутские записи, чтобы построить рейтинг.</div>`;const data=[...items].sort((a,b)=>b.mean-a.mean).slice(0,7),W=640,H=225,L=105,R=35,T=12,row=27,max=Math.max(20,...data.map(s=>s.mean))*1.12;let svg=`<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Средняя оценка вклада команд в модельных очках">`;[0,.25,.5,.75,1].forEach(f=>{const x=L+(W-L-R)*f;svg+=`<line class="chart-grid" x1="${x}" y1="${T-3}" x2="${x}" y2="${H-24}"/><text class="chart-label" x="${x}" y="${H-7}" text-anchor="middle">${Math.round(max*f)}</text>`;});data.forEach((d,i)=>{const y=T+i*row,w=Math.max(2,(W-L-R)*d.mean/max);svg+=`<text class="chart-label" x="${L-10}" y="${y+11}" text-anchor="end">${esc(d.team.number)}</text><rect class="chart-bar ${i===0?'top':i>4?'soft':''}" x="${L}" y="${y}" width="${w}" height="13" rx="5"/><text class="chart-value" x="${Math.min(W-24,L+w+7)}" y="${y+11}">${fmt(d.mean)}</text>`;});return svg+`<line class="axis-line" x1="${L}" y1="${H-23}" x2="${W-R}" y2="${H-23}"/><text class="chart-label" x="${(L+W-R)/2}" y="${H+8}" text-anchor="middle">Оценка вклада, модельные очки за матч</text></svg>`;}
function skillBars(s){return`<div class="profile-bars">${[['AUTO','auto'],['HIVE','hive'],['FLOWER','flower'],['Надёжность','reliability']].map(([l,k])=>`<div class="profile-row"><span class="profile-label">${l}</span><div class="profile-track"><div class="profile-fill" style="width:${Math.round(s.profile[k])}%"></div></div><span class="profile-value">${Math.round(s.profile[k])}</span></div>`).join('')}</div><div class="chart-note">Профиль нормирован по игровым задачам BIOBUZZ · 0–100</div>`;}
function overviewRows(items){if(!items.length)return`<tr><td colspan="5"><div class="empty-state"><strong>Пока нет записей</strong>Добавьте скаутские наблюдения или импортируйте CSV.</div></td></tr>`;return[...items].sort((a,b)=>b.mean-a.mean).slice(0,6).map(s=>`<tr><td><div class="team-cell"><span class="team-avatar">${initials(s.team)}</span><div><div class="team-name">${esc(s.team.name)}</div><div class="team-no">${esc(s.team.number)} · ${esc(s.team.region||'Регион не указан')}</div></div></div></td><td>${fmt(s.mean)} <span class="subtle">± ${fmt(s.sd)}</span></td><td>${s.count}</td><td>${badge(priority(s))}</td><td><span class="confidence"><i></i>${s.confidence}</span></td></tr>`).join('');}
function renderOverview(){const ss=allStats(),ranked=ss.filter(s=>s.count).sort((a,b)=>b.mean-a.mean),top=ranked[0],total=db.records.filter(r=>!db.meta.eventCode||r.eventCode===db.meta.eventCode).length;main.innerHTML=`${head('Турнирный обзор',`Ивент: ${db.meta.eventName||'не выбран'} · статистика по активному коду ${db.meta.eventCode||'(все ивенты)'}.` ,`<button class="button button-secondary" data-page="teams">Все команды</button><button class="button button-primary" data-action="go-scout">+ Записать матч</button>`)}${banner()}<section class="kpi-grid">${kpi('Команды в пуле',db.teams.length,'в текущем скаутинге','T')}${kpi('Наблюдения',total,db.meta.demo?'демо-записи':'сохранённые записи','S')}${kpi('Средняя оценка вклада',ranked.length?fmt(avg(ranked.map(s=>s.mean))):'—','модельные очки за матч','∑')}${kpi('Полнота данных',ranked.length?`${Math.round(ranked.filter(s=>s.count>=4).length/ranked.length*100)}%`:'—','команд с 4+ наблюдениями','D')}</section><section class="dashboard-grid"><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Команды по оценке вклада</h2><div class="panel-subtitle">Среднее модельное значение по матчевым записям</div></div><span class="pill">${MODEL_VERSION}</span></div><div class="chart-wrap">${avgChart(ss)}</div><div class="chart-note">Оценка по скаутированным действиям, не официальный счёт.</div></article><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Профиль лидера</h2><div class="panel-subtitle">${top?`${esc(top.team.number)} · ${esc(top.team.name)}`:'Добавьте данные для профиля'}</div></div>${top?badge(priority(top)):''}</div>${top?skillBars(top):`<div class="chart-empty">График появится после первого наблюдения.</div>`}</article></section><section class="recent-grid"><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Командный рейтинг</h2><div class="panel-subtitle">Результат · разброс · объём выборки</div></div><button class="button button-quiet button-small" data-page="teams">Открыть список</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Команда</th><th>Оценка</th><th>Матчи</th><th>Класс</th><th>Доверие</th></tr></thead><tbody>${overviewRows(ranked)}</tbody></table></div></article><aside class="notice-card"><div><span class="eyebrow">ПОДСКАЗКА</span><h3>Сила пары — в покрытии задач</h3><p>Сравните автономию, HIVE, FLOWER и надёжность обеих команд. Система объясняет основу рекомендации; решение остаётся за капитаном.</p></div><div class="notice-link" data-page="analysis">Перейти к анализу пары →</div></aside></section>`;}
function recentRecords(){const rs=[...db.records].filter(r=>!db.meta.eventCode||r.eventCode===db.meta.eventCode).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||b.matchNo-a.matchNo).slice(0,12);if(!rs.length)return`<tr><td colspan="6"><div class="empty-state"><strong>Скаутинг пока пуст</strong>Запишите матч или загрузите CSV.</div></td></tr>`;return rs.map(r=>{const t=team(r.teamId),b=breakdown(r);return`<tr><td>${esc(r.eventCode||'—')}</td><td>${esc(r.matchNo||'—')}</td><td><div class="team-cell"><span class="team-avatar">${initials(t)}</span><div><div class="team-name">${esc(t?.name||r.teamId)}</div><div class="team-no">${esc(t?.number||r.teamId)}</div></div></div></td><td>${fmt(b.total,0)}</td><td>${esc(r.scout||'—')}</td><td><button class="icon-button" data-action="delete-record" data-id="${esc(r.id)}">Удалить</button></td></tr>`;}).join('');}
function scoutForm(){return`<form class="form-grid" data-form="scout"><div class="field"><label>Команда *</label><select name="teamId" required>${db.teams.map(t=>opt(t)).join('')}</select></div><div class="field"><label>Номер матча</label><input name="matchNo" type="number" min="1" placeholder="Например, 12"></div><div class="field"><label>Код / название ивента</label><input name="eventCode" value="${esc(db.meta.eventCode||'')}"></div><div class="field"><label>Дата</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="form-section">Автономный период</div><div class="field"><label>HIVE TIP в Auto</label><input name="autoHiveTips" type="number" min="0" max="10" value="0"></div><div class="field"><label>Элементы, оставшиеся в CELL</label><input name="cellItems" type="number" min="0" max="40" value="0"><small>Считайте элементы в восходящих CELL после остановки матча; 2 очка за элемент альянсу.</small></div><label class="check-field"><input name="autoLeave" type="checkbox"><span>Робот покинул стену · 3 очка</span></label><label class="check-field"><input name="autoPark" type="checkbox"><span>Парковка Auto · 5 очков</span></label><div class="form-section">TeleOp и финал</div><div class="field"><label>HIVE TIP в TeleOp</label><input name="teleopHiveTips" type="number" min="0" max="10" value="0"></div><div class="field"><label>Элементы, помещённые роботом в FLOWER</label><input name="flowerPlaced" type="number" min="0" max="40" value="0"><small>Фиксируйте действие робота в последние 60 секунд; это показатель цикла, а не дополнительные очки.</small></div><div class="field"><label>Элементы в принадлежащих FLOWER</label><input name="ownedFlowerItems" type="number" min="0" max="40" value="0"><small>Записывайте только вклад этого робота; элементы FLOWER приносят очки альянсу, если тот владеет цветком.</small></div><div class="field"><label>Бонусы за нижний NECTAR</label><input name="bottomNectar" type="number" min="0" max="4" value="0"></div><div class="field"><label>Элементы, доставленные роботом в GARDEN</label><input name="gardenItems" type="number" min="0" max="40" value="0"><small>Очки принадлежат альянсу соответствующего GARDEN, а не роботу.</small></div><div class="field"><label>Штрафы MINOR FOUL</label><input name="penalties" type="number" min="0" max="20" value="0"></div><div class="field"><label>Уверенность наблюдения</label><select name="confidence"><option value="high">Высокая</option><option value="medium" selected>Средняя</option><option value="low">Низкая</option></select></div><label class="check-field"><input name="teleopPark" type="checkbox"><span>Парковка TeleOp · 5 очков</span></label><label class="check-field"><input name="disabled" type="checkbox"><span>Робот отключался</span></label><div class="field"><label>Имя скаута / источник</label><input name="scout" placeholder="Например, Алия / видео"></div><div class="field span-2"><label>Короткая заметка</label><textarea name="notes" placeholder="Стабильность механизма, сбои, особенности цикла..."></textarea></div><div class="field span-2"><div class="rule-callout">Модель очков: ${MODEL_VERSION}. FLOWER scoring начинается при 60 секундах до конца. Заполняйте только вклад выбранной команды и не дублируйте общие очки альянса в обеих командных записях. Модель оценивает наблюдаемый вклад, а не официальный счёт.</div></div><div class="form-actions"><button type="reset" class="button button-secondary">Очистить</button><button class="button button-primary" type="submit">Сохранить наблюдение</button></div></form>`;}
function renderScouting(){main.innerHTML=`${head('Скаутинг матча','Записывайте факты по каждому роботу. Данные сохраняются на этом устройстве.',`<button class="button button-secondary" data-page="data">Импорт CSV</button>`)}${banner()}<section class="section-grid"><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Новое наблюдение</h2><div class="panel-subtitle">Одна запись — одна команда в одном матче</div></div><span class="pill">Офлайн</span></div>${scoutForm()}</article><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Памятка скауту</h2><div class="panel-subtitle">Фиксируйте только то, что можно подтвердить.</div></div></div><div class="rule-callout"><strong>HIVE:</strong> запишите TIP отдельно для Auto и TeleOp; один TIP стоит 20 игровых очков.</div><div class="rule-callout"><strong>FLOWER:</strong> фиксируйте элементы в принадлежащих альянсу цветках и бонусы за нижний NECTAR.</div><div class="rule-callout"><strong>Надёжность:</strong> отмечайте поломки, отключения и низкую уверенность. Не заполняйте пропуски догадками.</div><p class="chart-note">Проверяйте последние Competition Manual и Team Updates перед турниром.</p><div class="head-actions" style="margin-top:14px"><button class="button button-secondary button-small" data-action="download-template">Скачать шаблон CSV</button></div></article></section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2 class="panel-title">Последние наблюдения</h2><div class="panel-subtitle">${db.records.length} записей в локальной базе</div></div><button class="button button-quiet button-small" data-page="data">Экспортировать данные</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ивент</th><th>Матч</th><th>Команда</th><th>Оценка вклада</th><th>Источник</th><th></th></tr></thead><tbody>${recentRecords()}</tbody></table></div></section>`;}
function renderTeams(){const list=allStats().filter(s=>`${s.team.number} ${s.team.name} ${s.team.region}`.toLowerCase().includes(searchTerm.toLowerCase())).filter(s=>teamFilter==='all'||priority(s)===teamFilter).sort((a,b)=>b.mean-a.mean);const add=`<button class="button button-primary" data-action="add-team">+ Добавить команду</button>`;
if(activeTeam){const s=stats(team(activeTeam));if(!s){activeTeam=null;return renderTeams();}const t=s.team;main.innerHTML=`<div class="page-head"><div><button class="button button-quiet button-small" data-action="back-teams">← Все команды</button><div class="team-profile-head" style="margin-top:13px"><span class="team-avatar">${initials(t)}</span><div><h2>${esc(t.name)}</h2><p>${esc(t.number)} · ${esc(t.region||'Регион не указан')} · ${esc(t.style||'Скаутируемая команда')}</p></div></div></div><div class="head-actions"><button class="button button-primary" data-action="scout-team" data-id="${esc(t.id)}">Записать матч</button></div></div>${banner()}<div class="mini-stat-grid"><div class="mini-stat"><span>Наблюдений</span><strong>${s.count}</strong></div><div class="mini-stat"><span>Оценка вклада</span><strong>${fmt(s.mean)}</strong></div><div class="mini-stat"><span>Разброс (σ)</span><strong>± ${fmt(s.sd)}</strong></div><div class="mini-stat"><span>Уверенность</span><strong>${s.confidence}</strong></div></div><section class="dashboard-grid"><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Игровой профиль</h2><div class="panel-subtitle">Нормированные показатели, 0–100</div></div></div>${skillBars(s)}<div class="rule-callout">Оценка вклада — сумма наблюдаемых действий, а не официальный счёт. Часть BIOBUZZ-очков присуждается всему альянсу.</div></article><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Средние действия за матч</h2><div class="panel-subtitle">По ${s.count} записям</div></div></div><div class="breakdown-grid"><div class="breakdown-item"><span>HIVE TIP · Auto</span><strong>${fmt(s.autoTips)}</strong></div><div class="breakdown-item"><span>HIVE TIP · TeleOp</span><strong>${fmt(s.teleopTips)}</strong></div><div class="breakdown-item"><span>FLOWER размещено / матч</span><strong>${fmt(s.flowerPlaced)}</strong></div><div class="breakdown-item"><span>FLOWER эл-ты*</span><strong>${fmt(s.flowerOwned)}</strong></div><div class="breakdown-item"><span>Парковка TeleOp</span><strong>${Math.round(s.parkRate*100)}%</strong></div></div><div class="chart-note">* В цветках, принадлежащих альянсу.</div></article></section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2 class="panel-title">Матчевые наблюдения</h2><div class="panel-subtitle">Вклад и отдельные действия</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Матч</th><th>Auto</th><th>HIVE TIP</th><th>FLOWER</th><th>GARDEN</th><th>Оценка</th><th>Уверенность</th></tr></thead><tbody>${s.records.map(r=>{const b=breakdown(r);return`<tr><td>${esc(r.eventCode)} · ${esc(r.matchNo)}</td><td>${fmt(b.auto,0)}</td><td>${num(r.autoHiveTips)+num(r.teleopHiveTips)}</td><td>${num(r.ownedFlowerItems)} + ${num(r.bottomNectar)} бонус.</td><td>${num(r.gardenItems)}</td><td>${fmt(b.total,0)}</td><td>${esc(r.confidence)}</td></tr>`;}).join('')||`<tr><td colspan="7"><div class="empty-state">Для команды ещё нет наблюдений.</div></td></tr>`}</tbody></table></div></section>`;return;}
main.innerHTML=`${head('Команды','Сравнивайте игровые профили, стабильность и объём скаутских данных.',add)}${banner()}<div class="toolbar"><div class="toolbar-group"><input class="toolbar-input" id="teamSearch" placeholder="Найти команду или регион" value="${esc(searchTerm)}"><select class="toolbar-input filter-select" id="teamFilter"><option value="all">Все приоритеты</option><option value="A" ${teamFilter==='A'?'selected':''}>A · основной</option><option value="Б" ${teamFilter==='Б'?'selected':''}>Б · следующий этап</option><option value="В" ${teamFilter==='В'?'selected':''}>В · при ресурсах</option></select></div><span class="subtle">${list.length} команд</span></div><section class="team-list">${list.length?list.map(s=>`<article class="team-row"><div class="team-cell"><span class="team-avatar">${initials(s.team)}</span><div><div class="team-name">${esc(s.team.name)}</div><div class="team-no">${esc(s.team.number)} · ${esc(s.team.region||'Регион не указан')}</div></div></div><div><div class="team-stat-label">Оценка вклада</div><div class="team-stat-val">${fmt(s.mean)} <span class="subtle">± ${fmt(s.sd)}</span></div></div><div class="hide-sm"><div class="team-stat-label">Матчей</div><div class="team-stat-val">${s.count}</div></div><div class="hide-md"><div class="team-stat-label">FLOWER / матч</div><div class="team-stat-val">${fmt(s.flower)}</div></div><div class="hide-md"><div class="team-stat-label">Стабильность</div><div class="team-stat-val">${Math.round(s.consistency)}%</div></div><div class="row-actions"><button class="icon-button" data-action="open-team" data-id="${esc(s.team.id)}">Профиль</button><button class="icon-button" data-action="scout-team" data-id="${esc(s.team.id)}">+ Матч</button></div></article>`).join(''):`<div class="panel empty-state"><strong>Ничего не найдено</strong>Добавьте команду или измените фильтр.</div>`}</section>`;
document.getElementById('teamSearch')?.addEventListener('input',e=>{searchTerm=e.target.value;const p=e.target.selectionStart;renderTeams();const q=document.getElementById('teamSearch');q?.focus();q?.setSelectionRange(p,p);});document.getElementById('teamFilter')?.addEventListener('change',e=>{teamFilter=e.target.value;renderTeams();});}
function teamSelect(key,id){return`<select class="select-team" data-selection="${key}">${db.teams.map(t=>opt(t,id)).join('')}</select>`;}
function allianceCards(){const[a,b,c,d]=analysisSelection,one=pairModel(a,b),two=pairModel(c,d);if(!one||!two)return`<div class="empty-state">Добавьте не менее четырёх команд.</div>`;return`<section class="comparison-grid"><article class="alliance-card"><div class="alliance-head"><span class="alliance-label"><i class="alliance-swatch"></i>Альянс 1</span><span class="subtle">${fmt(one.mean,0)} мод. очков</span></div>${teamSelect('a',a)}<div class="select-pair-line"><span class="subtle">в паре с</span><span class="pair-plus">+</span><span class="subtle">команда 2</span></div>${teamSelect('b',b)}</article><div class="synergy-center"><span class="eyebrow">ПОКРЫТИЕ ЗАДАЧ ПАРОЙ</span><div class="synergy-score">${Math.round(one.score)}</div><div class="synergy-label">индекс синергии из 100</div><div class="synergy-meter"><i style="width:${one.score}%"></i></div><div class="synergy-caption">Профили Auto, HIVE, FLOWER, стабильность и объём скаутинга. Это не вероятность победы.</div></div><article class="alliance-card"><div class="alliance-head"><span class="alliance-label"><i class="alliance-swatch blue"></i>Альянс 2</span><span class="subtle">${fmt(two.mean,0)} мод. очков</span></div>${teamSelect('c',c)}<div class="select-pair-line"><span class="subtle">в паре с</span><span class="pair-plus">+</span><span class="subtle">команда 2</span></div>${teamSelect('d',d)}</article></section><div class="breakdown-grid"><div class="breakdown-item"><span>Покрытие профилей</span><strong>${Math.round(one.cover)} / 100</strong></div><div class="breakdown-item"><span>Разница профилей</span><strong>${Math.round(one.complement)} / 100</strong></div><div class="breakdown-item"><span>Средняя стабильность</span><strong>${Math.round(one.stability)}%</strong></div><div class="breakdown-item"><span>Наблюдений в паре</span><strong>${one.a.count+one.b.count}</strong></div></div>`;}
function histogram(values){if(!values?.length)return'';const W=520,H=175,L=40,R=18,T=15,B=33,bins=20,min=Math.min(...values),max=Math.max(...values),span=Math.max(10,max-min),counts=Array(bins).fill(0);values.forEach(v=>counts[clamp(Math.floor((v-min)/span*bins),0,bins-1)]++);const maxC=Math.max(1,...counts);const bw=(W-L-R)/bins;let s=`<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Распределение разницы очков в симуляции">`;[0,.5,1].forEach(f=>{const y=T+(H-T-B)*(1-f);s+=`<line class="chart-grid" x1="${L}" y1="${y}" x2="${W-R}" y2="${y}"/><text class="chart-label" x="${L-7}" y="${y+3}" text-anchor="end">${Math.round(maxC*f)}</text>`;});counts.forEach((v,i)=>{const h=(H-T-B)*v/maxC;s+=`<rect x="${L+i*bw+1}" y="${H-B-h}" width="${Math.max(1,bw-2)}" height="${h}" rx="2" fill="${i<bins/2?'#cf9a55':'#4e8a68'}" opacity=".88"/>`;});return s+`<line class="axis-line" x1="${L}" y1="${H-B}" x2="${W-R}" y2="${H-B}"/><text class="chart-label" x="${L}" y="${H-10}">−${Math.round(span/2)}</text><text class="chart-label" x="${(W+L-R)/2}" y="${H-10}" text-anchor="middle">0</text><text class="chart-label" x="${W-R}" y="${H-10}" text-anchor="end">+${Math.round(span/2)}</text><text class="chart-label" x="${(W+L-R)/2}" y="${H+5}" text-anchor="middle">Разница модельных очков (Альянс 1 − Альянс 2)</text></svg>`;}
function renderAnalysis(){const ok=db.teams.length>=4;main.innerHTML=`${head('Анализ альянса','Сравните покрытие задач и оцените исход серии виртуальных матчей.',`<span class="pill">Модель · ${MODEL_VERSION}</span>`)}${banner()}${ok?allianceCards():`<section class="panel empty-state"><strong>Нужно минимум четыре команды</strong>Добавьте команды и наблюдения для анализа.</section>`}<section class="analysis-lower"><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Симулятор матчей</h2><div class="panel-subtitle">1 000 итераций по средним и разбросу наблюдений</div></div><button class="button button-primary button-small" data-action="simulate" ${ok?'':'disabled'}>Запустить</button></div>${simResult?`<div class="sim-result"><div class="prob-row"><span>Победа A1</span><div class="prob-track"><i style="width:${simResult.winPct}%"></i></div><strong>${simResult.winPct}%</strong></div><div class="prob-row"><span>Победа A2</span><div class="prob-track"><i style="width:${simResult.lossPct}%;background:#c98744"></i></div><strong>${simResult.lossPct}%</strong></div><div class="prob-row"><span>Ничья</span><div class="prob-track"><i style="width:${simResult.tiePct}%;background:#93a49a"></i></div><strong>${simResult.tiePct}%</strong></div>${histogram(simResult.diff)}<div class="sim-diff"><div><span>Средний счёт A1</span><strong>${fmt(simResult.mean1,0)}</strong></div><div><span>Средний счёт A2</span><strong>${fmt(simResult.mean2,0)}</strong></div><div><span>Интервал победы A1 · 95%</span><strong>${simResult.ciLow}–${simResult.ciHigh}%</strong></div></div><div class="risk-note">${esc(simResult.risk)}</div></div>`:`<div class="result-box"><strong>Запусти симуляцию</strong><p>При малом числе матчей интервал неопределённости будет широким. Модель не учитывает полностью защиту, взаимодействия команд и решения судей.</p></div>`}</article><article class="panel"><div class="panel-head"><div><h2 class="panel-title">Как читать индекс</h2><div class="panel-subtitle">Сравнительная оценка, не гарантия победы</div></div></div><p class="chart-note" style="font-size:10px;line-height:1.65">Индекс объединяет покрытие профилей, комплементарность, стабильность и объём скаутинга. Он полезен для первичного сравнения пар, но его нужно калибровать на реальных матчах.</p><div class="rule-callout">Расчёт очков — оценка по наблюдаемым действиям. Он не моделирует полностью защиту, конкуренцию за ресурсы, владение FLOWER соперником и работу рефери.</div><div class="comparison-robot">Сохраняйте прогноз до матча, затем сверяйте его с официальным результатом.</div></article></section>`;document.querySelectorAll('[data-selection]').forEach(el=>el.addEventListener('change',e=>{analysisSelection[{a:0,b:1,c:2,d:3}[e.target.dataset.selection]]=e.target.value;simResult=null;renderAnalysis();}));}
function simulate(){const[a,b,c,d]=analysisSelection,left=pairModel(a,b),right=pairModel(c,d);if(!left||!right){toast('Выбери четыре команды.','error');return;}let wins=0,loss=0,ties=0;const diff=[];const normal=()=>{let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);};for(let i=0;i<1000;i++){const x=left.mean+normal()*left.sd,y=right.mean+normal()*right.sd;diff.push(x-y);if(Math.abs(x-y)<1)ties++;else if(x>y)wins++;else loss++;}const p=(wins+ties*.5)/1000,margin=1.96*Math.sqrt(p*(1-p)/1000)*100,flowerGap=left.a.flower+left.b.flower-right.a.flower-right.b.flower;let risk;if(left.a.count+left.b.count<4||right.a.count+right.b.count<4)risk='Мало наблюдений: прогноз предварительный. Соберите больше матчей перед решением драфта.';else if(Math.abs(flowerGap)>12)risk=flowerGap<0?'Зона внимания: у Альянса 1 ниже наблюдаемый вклад в FLOWER. Оцените контроль и точность последней минуты.':'Зона внимания: у Альянса 2 ниже наблюдаемый вклад в FLOWER. Проверьте, чем закрыть разрыв.';else risk='Большого разрыва профилей FLOWER не видно. На исход могут сильнее влиять HIVE, Auto, штрафы и события матча.';simResult={winPct:Math.round(wins/10),lossPct:Math.round(loss/10),tiePct:Math.round(ties/10),mean1:left.mean,mean2:right.mean,ciLow:Math.round(clamp(p*100-margin,0,100)),ciHigh:Math.round(clamp(p*100+margin,0,100)),diff,risk};renderAnalysis();}
function renderDraft(){db.draft ||= {captain:db.teams[0]?.id||'',picked:[],removed:[]};const cap=team(db.draft.captain),picked=(db.draft.picked||[]).filter(id=>team(id)&&id!==cap?.id).slice(0,1),removed=db.draft.removed||[];const candidates=db.teams.filter(t=>t.id!==cap?.id&&!removed.includes(t.id)&&!picked.includes(t.id)).map(t=>({team:t,model:cap?pairModel(cap.id,t.id):null})).sort((a,b)=>(b.model?.score||0)-(a.model?.score||0));main.innerHTML=`${head('Доска драфта','Помечайте доступных соперников и фиксируйте выбор капитана.',`<button class="button button-secondary" data-action="reset-draft">Сбросить доску</button>`)}${banner()}<section class="draft-layout"><aside class="draft-side"><span class="eyebrow">АЛЬЯНС-КАПИТАН</span><h3 style="margin-top:7px">Выбери команду-капитана</h3><select id="draftCaptain" class="select-team">${db.teams.map(t=>opt(t,db.draft.captain)).join('')}</select><div class="eyebrow" style="margin-top:13px">СОСТАВ АЛЬЯНСА</div><div class="picked-slot"><small>Капитан</small><strong>${cap?esc(teamLabel(cap)):'Выбери команду'}</strong></div><div class="picked-slot"><small>Выбранный партнёр</small><strong>${picked[0]?esc(teamLabel(team(picked[0]))):'Пока не выбран'}</strong></div><p style="font-size:8px;color:#a8beb2;line-height:1.55;margin:12px 1px 0">Подсказки основаны на скаутинге; решение принимает капитан.</p></aside><div class="draft-main"><div class="draft-toolbar"><strong>Доступные команды</strong><span>${candidates.length} в пуле · сортировка по синергии</span></div><section class="draft-candidates">${candidates.length?candidates.map((x,i)=>`<article class="candidate-row"><span class="candidate-rank">${String(i+1).padStart(2,'0')}</span><div><h4>${esc(x.team.number)} · ${esc(x.team.name)}</h4><p>${esc(x.team.style||x.team.region||'Профиль команды')}</p></div><div class="hide-sm"><div class="team-stat-label">Индекс пары</div><div class="candidate-score">${x.model?Math.round(x.model.score):'—'}</div></div><div class="hide-md"><div class="team-stat-label">Оценка вклада</div><div class="candidate-score">${x.model?fmt(x.model.mean,0):'—'}</div></div><div class="candidate-actions"><button class="button button-primary button-small" data-action="pick" data-id="${esc(x.team.id)}">Выбрать</button><button class="icon-button" data-action="mark-taken" data-id="${esc(x.team.id)}" title="Уже выбрана другим альянсом">Взяли</button></div></article>`).join(''):`<div class="panel empty-state"><strong>Нет доступных команд</strong>Сбросьте статусы или проверьте список.</div>`}</section>${removed.length?`<div class="removed-list"><strong>Выбраны другими альянсами</strong>${removed.map(id=>team(id)).filter(Boolean).map(t=>`<span class="removed-chip">${esc(t.number)} · ${esc(t.name)} <button class="icon-button" data-action="restore-team" data-id="${esc(t.id)}">Вернуть</button></span>`).join('')}</div>`:''}${picked.length?`<div class="result-box"><strong>Партнёр выбран</strong><p>${esc(teamLabel(team(picked[0])))} добавлен к капитану в локальную доску. <button class="icon-button" data-action="unpick">Отменить выбор</button></p></div>`:''}</div></section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2 class="panel-title">Основа подсказки</h2><div class="panel-subtitle">Покрытие профилей и полнота скаутинга</div></div></div><div class="breakdown-grid"><div class="breakdown-item"><span>Пара оценивается по</span><strong>4 профилям</strong></div><div class="breakdown-item"><span>Решение принимает</span><strong>Капитан</strong></div><div class="breakdown-item"><span>Источник</span><strong>${db.meta.demo?'Демо-записи':'Ваш скаутинг'}</strong></div><div class="breakdown-item"><span>Партнёров выбрано</span><strong>${picked.length} / 1</strong></div></div></section>`;document.getElementById('draftCaptain')?.addEventListener('change',e=>{db.draft.captain=e.target.value;db.draft.picked=[];save();renderDraft();});}
function renderData(){main.innerHTML=`${head('Импорт и экспорт','Резервируйте базу и переносите скаутинг между устройствами.',`<button class="button button-primary" data-action="export-json">Скачать резервную копию</button>`)}${banner()}<section class="data-grid"><article class="data-tile"><h3>Экспорт CSV</h3><p>Выгрузите записи наблюдений для таблиц и анализа в Python.</p><button class="button button-secondary button-small" data-action="export-csv">Экспортировать наблюдения</button><button class="button button-secondary button-small" data-action="download-template">Пустой шаблон</button></article><article class="data-tile"><h3>Импорт CSV</h3><p>Загрузите записи из шаблона. Новые номера автоматически станут карточками команд.</p><input class="file-input-hidden" id="csvInput" type="file" accept=".csv,text/csv"><button class="button button-secondary button-small" data-action="import-csv">Выбрать CSV</button></article><article class="data-tile"><h3>Резервная копия JSON</h3><p>Включает команды, настройки турнира, доску драфта и все наблюдения.</p><button class="button button-secondary button-small" data-action="export-json">Экспортировать</button><input class="file-input-hidden" id="jsonInput" type="file" accept=".json,application/json"><button class="button button-secondary button-small" data-action="import-json">Восстановить</button></article><article class="data-tile"><h3>Управление данными</h3><p>Удалите учебные данные и начните с чистой базы. Сначала сохраните резервную копию.</p><button class="button button-danger button-small" data-action="clear-data">Удалить локальные данные</button><button class="button button-secondary button-small" data-action="restore-demo">Восстановить демо</button></article><article class="data-tile wide"><h3>Официальные данные FTC Events API</h3><p>Серверный прокси хранит персональные FTC API credentials вне браузера. Код сезона — год завершения сезона (например, 2027). Результаты могут появиться после матча и синхронизации FIRST.</p><div class="toolbar-group" style="margin:10px 0"><input class="toolbar-input" id="apiSeason" aria-label="Год сезона FTC" value="${esc((db.meta.season||'2026-2027').replace(/\D/g,'').slice(-4)||'2027')}" placeholder="2027"><input class="toolbar-input" id="apiEventCode" aria-label="Код ивента FIRST" value="${db.meta.demo?'':esc(db.meta.eventCode||'')}" placeholder="Код ивента, например KZAL"></div><div class="toolbar-group" style="margin:10px 0"><button class="button button-secondary button-small" data-action="api-events">Загрузить список ивентов</button><select class="toolbar-input" id="apiEventSelect" aria-label="Выбрать официальный ивент"><option value="">Сначала загрузите список ивентов</option></select></div><button class="button button-secondary button-small" data-action="api-check">Проверить подключение</button><button class="button button-primary button-small" data-action="api-sync">Загрузить команды и результаты</button><div id="apiOutput" style="margin-top:12px">${officialView||'<div class="data-source">Сначала настройте FTC_API_USERNAME и FTC_API_TOKEN на локальном сервере. Токен не вводится в это окно и не сохраняется в браузере.</div>'}</div><div class="data-source" style="margin-top:10px">FIRST просит указывать ссылку на API и запрещает коммерческое использование его данных. <a href="https://ftc-events.firstinspires.org/services/API" target="_blank" rel="noreferrer">Условия и регистрация ↗</a> · <a href="https://ftc-events.firstinspires.org/api-docs/index.html" target="_blank" rel="noreferrer">Документация ↗</a></div></article><article class="data-tile wide"><h3>Колонки CSV</h3><p><span class="code-chip">teamNumber,eventCode,eventName,matchNo,date,autoLeave,autoPark,autoHiveTips,teleopHiveTips,cellItems,flowerPlaced,ownedFlowerItems,bottomNectar,gardenItems,teleopPark,penalties,disabled,confidence,scout,notes</span></p><p>Флажки принимают true/false, 1/0 или да/нет. Экспортируйте шаблон, чтобы получить точные заголовки.</p></article></section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2 class="panel-title">Настройки турнира</h2><div class="panel-subtitle">Применяются к новым наблюдениям</div></div></div><form class="form-grid" data-form="settings"><div class="field"><label>Название ивента</label><input name="eventName" value="${esc(db.meta.eventName||'')}"></div><div class="field"><label>Код ивента</label><input name="eventCode" value="${esc(db.meta.eventCode||'')}"></div><div class="field"><label>Сезон</label><input name="season" value="${esc(db.meta.season||'2026-2027')}"></div><div class="form-actions"><button class="button button-primary" type="submit">Сохранить настройки</button></div></form></section>`;}

async function loadApiEvents(){const season=document.getElementById('apiSeason')?.value.trim()||'2027',select=document.getElementById('apiEventSelect');if(!/^\d{4}$/.test(season)){toast('Укажи четырёхзначный год FTC сезона.','error');return;}select.innerHTML='<option value="">Загружаю список…</option>';try{const data=await apiJson('/api/ftc/events?season='+encodeURIComponent(season)),events=data.events||[];select.innerHTML='<option value="">Выбери ивент…</option>'+events.map(e=>{const code=e.code||e.eventCode||'',name=e.name||e.eventName||code,location=[e.city,e.stateProv].filter(Boolean).join(', ');return '<option value="'+esc(code)+'" data-name="'+esc(name)+'">'+esc(name)+' · '+esc(location||code)+'</option>';}).join('');select.onchange=()=>{const option=select.selectedOptions[0];document.getElementById('apiEventCode').value=select.value;selectedEventName=option?.dataset.name||'';};toast('Загружено ивентов: '+events.length+'.');}catch(e){select.innerHTML='<option value="">Не удалось загрузить ивенты</option>';toast(e.message,'error');}}
async function apiJson(url){const response=await fetch(url,{headers:{Accept:'application/json'}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.detail||`Сервер вернул ${response.status}.`);return data;}
function apiOutput(html){officialView=html;const box=document.getElementById('apiOutput');if(box)box.innerHTML=html;}
async function checkApi(){try{const status=await apiJson('/api/health');apiOutput(status.official_api_configured?`<div class="data-source"><strong>Подключено.</strong> Сервер готов обращаться к ${esc(status.source)}. Учётные данные не передаются браузеру.</div>`:`<div class="data-source">Сервер работает, но FTC API credentials ещё не заданы. Установите FTC_API_USERNAME и FTC_API_TOKEN в окружении сервера.</div>`);}catch(e){apiOutput(`<div class="data-source">${esc(e.message)} Запустите защищённый локальный сервер из папки проекта по инструкции README.</div>`);}}
async function syncOfficial(){const season=document.getElementById('apiSeason')?.value.trim()||'2027',code=document.getElementById('apiEventCode')?.value.trim()||'';if(!/^\d{4}$/.test(season)){toast('Укажи четырёхзначный год FTC сезона.','error');return;}if(!/^[A-Za-z0-9]{3,20}$/.test(code)){toast('Укажи код ивента FIRST из 3–20 латинских букв или цифр.','error');return;}apiOutput('<div class="data-source">Загружаю официальную командную таблицу и завершённые матчи…</div>');try{const [teamData,matchData]=await Promise.all([apiJson(`/api/ftc/teams?season=${encodeURIComponent(season)}&event_code=${encodeURIComponent(code)}`),apiJson(`/api/ftc/matches?season=${encodeURIComponent(season)}&event_code=${encodeURIComponent(code)}&tournament_level=qual`)]);const officialTeams=teamData.teams||[],matches=matchData.matches||[];let replaceDemo=false;if(db.meta.demo){replaceDemo=confirm('Заменить учебные данные официальным списком команд? Демонстрационные команды и матчи будут удалены.');if(replaceDemo){db.teams=[];db.records=[];db.meta.demo=false;db.draft={captain:'',picked:[],removed:[]};}}
if(!db.meta.demo){officialTeams.forEach(x=>{const no=String(x.teamNumber??x.displayTeamNumber??'').trim();if(!no)return;let t=db.teams.find(t=>t.number===no);if(!t){t={id:no,number:no,name:x.nameFull||x.nameShort||x.teamName||`Команда ${no}`,region:[x.city,x.stateProv].filter(Boolean).join(', '),style:'FTC Events API',notes:''};db.teams.push(t);}else{t.name=x.nameFull||x.nameShort||x.teamName||t.name;t.region=[x.city,x.stateProv].filter(Boolean).join(', ')||t.region;}});db.meta.eventCode=code.toUpperCase();db.meta.season=`${Number(season)-1}-${season}`;db.meta.eventName=selectedEventName||teamData.eventName||db.meta.eventName||`FTC · ${code.toUpperCase()}`;if(!db.draft.captain&&db.teams[0])db.draft.captain=db.teams[0].id;save();}
const resultRows=matches.slice(0,20).map(m=>`<tr><td>${esc(m.tournamentLevel||'qual')} ${esc(m.matchNumber??'')}</td><td>${esc((m.teams||[]).map(t=>`${t.station||''} ${t.teamNumber||''}`).join(' · ')||'—')}</td><td>${esc(m.scoreRedFinal??'—')}</td><td>${esc(m.scoreBlueFinal??'—')}</td><td>${Number(m.scoreRedFinal)>Number(m.scoreBlueFinal)?'Красный выиграл':Number(m.scoreBlueFinal)>Number(m.scoreRedFinal)?'Синий выиграл':'Ничья / нет данных'}</td></tr>`).join('');const note=db.meta.demo?'<p>Демо-набор оставлен; официальные команды показаны ниже для просмотра. Повторите загрузку и подтвердите замену, чтобы перейти на реальные данные.</p>':'<p>Список команд добавлен/обновлён. Официальные результаты показаны для сверки и не подменяют ручной скаутинг роботов.</p>';apiOutput(`<div class="data-source"><strong>${esc(code.toUpperCase())} · сезон ${esc(season)}</strong>${note}<div class="chart-note">Команд получено: ${officialTeams.length} · завершённых матчей в ответе: ${matches.length}</div><div class="table-wrap" style="margin-top:8px"><table class="data-table"><thead><tr><th>Матч</th><th>Команды</th><th>Красный</th><th>Синий</th><th>Статус победы</th></tr></thead><tbody>${resultRows||'<tr><td colspan="5">FIRST пока не вернул завершённые матчи для этого ивента и уровня турнира.</td></tr>'}</tbody></table></div></div>`);toast(`Получено команд: ${officialTeams.length}; матчей: ${matches.length}.`);render();}
catch(e){apiOutput(`<div class="data-source">${esc(e.message)} Скаутинг и анализ остаются доступны офлайн.</div>`);}}
function render(){document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.getElementById('pageCrumb').textContent=labels[page]||'Обзор';document.getElementById('eventLabel').textContent=db.meta.eventName||'Ивент не указан';({overview:renderOverview,scouting:renderScouting,teams:renderTeams,analysis:renderAnalysis,draft:renderDraft,data:renderData}[page]||renderOverview)();}
function toast(msg,type=''){const r=document.getElementById('toastRegion');r.innerHTML=`<div class="toast ${type}">${esc(msg)}</div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>r.innerHTML='',3300);}
function showModal(title,sub,body){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="modal-close" data-action="close-modal" aria-label="Закрыть">×</button></div>${body}</section></div>`;}
function closeModal(){document.getElementById('modalRoot').innerHTML='';}
function teamModal(){showModal('Добавить команду','Карточка появится в рейтинге и на доске драфта.',`<form class="form-grid" data-form="team"><div class="field"><label>Номер команды *</label><input name="number" required placeholder="Например, 31415"></div><div class="field"><label>Название *</label><input name="name" required placeholder="Название команды"></div><div class="field"><label>Регион</label><input name="region" placeholder="Город / регион"></div><div class="field"><label>Стиль робота</label><input name="style" placeholder="Например, сильный AUTO"></div><div class="form-actions"><button type="button" class="button button-secondary" data-action="close-modal">Отмена</button><button class="button button-primary" type="submit">Добавить команду</button></div></form>`);}
function download(name,text,type){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),800);}
const CSV=['teamNumber','eventCode','eventName','matchNo','date','autoLeave','autoPark','autoHiveTips','teleopHiveTips','cellItems','flowerPlaced','ownedFlowerItems','bottomNectar','gardenItems','teleopPark','penalties','disabled','confidence','scout','notes'];
function exportRow(r){const t=team(r.teamId)||{};return{teamNumber:t.number||r.teamId,eventCode:r.eventCode,eventName:r.eventName||db.meta.eventName,matchNo:r.matchNo,date:r.date,autoLeave:r.autoLeave,autoPark:r.autoPark,autoHiveTips:r.autoHiveTips,teleopHiveTips:r.teleopHiveTips,cellItems:r.cellItems,flowerPlaced:r.flowerPlaced,ownedFlowerItems:r.ownedFlowerItems,bottomNectar:r.bottomNectar,gardenItems:r.gardenItems,teleopPark:r.teleopPark,penalties:r.penalties,disabled:r.disabled,confidence:r.confidence,scout:r.scout,notes:r.notes};}
function csvEsc(v){const s=String(v??'');return/[",\r\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
function exportCSV(records=db.records){const txt=[CSV.join(','),...records.map(r=>{const x=exportRow(r);return CSV.map(k=>csvEsc(x[k])).join(',');})].join('\r\n');download('biobuzz-scouting.csv','\ufeff'+txt,'text/csv;charset=utf-8');toast(`${records.length} записей экспортировано.`);}
function parseCSV(text){const out=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"')quoted=true;else if(c===','){row.push(field);field='';}else if(c==='\n'){row.push(field.replace(/\r$/,''));field='';if(row.some(x=>x!==''))out.push(row);row=[];}else field+=c;}row.push(field.replace(/\r$/,''));if(row.some(x=>x!==''))out.push(row);if(!out.length)return[];const keys=out.shift().map(x=>x.trim().replace(/^\ufeff/,''));return out.map(line=>Object.fromEntries(keys.map((k,i)=>[k,(line[i]??'').trim()])));}
function bool(v){return['1','true','yes','да','y'].includes(String(v||'').trim().toLowerCase());}
function newRecord(x,id){return{id:`r-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,teamId:id,eventCode:x.eventCode||db.meta.eventCode||'',eventName:x.eventName||db.meta.eventName||'',matchNo:num(x.matchNo),date:x.date||new Date().toISOString().slice(0,10),autoLeave:bool(x.autoLeave),autoPark:bool(x.autoPark),autoHiveTips:num(x.autoHiveTips),teleopHiveTips:num(x.teleopHiveTips),cellItems:num(x.cellItems),flowerPlaced:num(x.flowerPlaced),ownedFlowerItems:num(x.ownedFlowerItems),bottomNectar:num(x.bottomNectar),gardenItems:num(x.gardenItems),teleopPark:bool(x.teleopPark),penalties:num(x.penalties),disabled:bool(x.disabled),confidence:['high','medium','low'].includes(x.confidence)?x.confidence:'medium',scout:x.scout||'',notes:x.notes||''};}
function importCSV(text){const data=parseCSV(text);if(!data.length)throw Error('В CSV нет записей.');if(!data[0].teamNumber&&!data[0].teamId)throw Error('Не найдена колонка teamNumber. Скачайте шаблон приложения.');let count=0;data.forEach(x=>{const no=String(x.teamNumber||x.teamId||'').trim();if(!no)return;let t=db.teams.find(t=>t.number===no||t.id===no);if(!t){t={id:no,number:no,name:x.teamName||`Команда ${no}`,region:x.region||'',style:'Импортировано',notes:''};db.teams.push(t);}db.records.push(newRecord(x,t.id));count++;});db.meta.demo=false;save();toast(`Импортировано записей: ${count}`);render();}
async function chooseFile(id,kind){const input=document.getElementById(id);input.onchange=async()=>{const f=input.files?.[0];if(!f)return;try{const txt=await f.text();if(kind==='csv')importCSV(txt);else{const next=JSON.parse(txt);if(!Array.isArray(next.teams)||!Array.isArray(next.records))throw Error('Это не резервная копия приложения.');if(!confirm('Заменить текущую базу этой резервной копией?'))return;db=next;db.meta.demo=false;save();toast('Резервная копия восстановлена.');render();}}catch(e){toast(e.message||'Ошибка чтения файла.','error');}input.value='';};input.click();}
function clearAll(){if(!confirm('Удалить все команды, записи и настройки из этого браузера? Сначала скачайте JSON-резервную копию.'))return;db={version:1,meta:{demo:false,eventName:'',eventCode:'',season:'2026-2027',updatedAt:new Date().toISOString()},teams:[],records:[],draft:{captain:'',picked:[],removed:[]}};save();page='overview';activeTeam=null;simResult=null;render();toast('Локальная база очищена.');}
function click(e){const nav=e.target.closest('[data-page]');if(nav){page=nav.dataset.page;activeTeam=null;render();return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
if(a==='go-scout'){page='scouting';activeTeam=null;render();}
else if(a==='add-team')teamModal();else if(a==='close-modal')closeModal();else if(a==='backdrop'&&e.target===el)closeModal();
else if(a==='open-team'){activeTeam=id;page='teams';render();}else if(a==='back-teams'){activeTeam=null;renderTeams();}
else if(a==='scout-team'){page='scouting';render();const s=document.querySelector('[data-form="scout"] [name="teamId"]');if(s)s.value=id;}
else if(a==='simulate')simulate();
else if(a==='pick'){db.draft.picked=[id];save();renderDraft();toast('Команда выбрана как партнёр.');}else if(a==='unpick'){db.draft.picked=[];save();renderDraft();}else if(a==='mark-taken'){db.draft.removed=[...new Set([...(db.draft.removed||[]),id])];save();renderDraft();toast('Команда отмечена как выбранная другим альянсом.');}else if(a==='restore-team'){db.draft.removed=(db.draft.removed||[]).filter(x=>x!==id);save();renderDraft();}
else if(a==='reset-draft'){db.draft={captain:db.draft.captain||db.teams[0]?.id||'',picked:[],removed:[]};save();renderDraft();toast('Доска сброшена.');}
else if(a==='delete-record'){if(!confirm('Удалить эту запись?'))return;db.records=db.records.filter(r=>r.id!==id);db.meta.demo=false;save();render();toast('Запись удалена.');}
else if(a==='export-json'){download('biobuzz-backup.json',JSON.stringify(db,null,2),'application/json');toast('Резервная копия скачана.');}
else if(a==='api-events')loadApiEvents();else if(a==='api-check')checkApi();else if(a==='api-sync')syncOfficial();else if(a==='export-csv')exportCSV();else if(a==='download-template')exportCSV([]);else if(a==='import-csv')chooseFile('csvInput','csv');else if(a==='import-json')chooseFile('jsonInput','json');else if(a==='clear-data')clearAll();
else if(a==='restore-demo'){if(db.records.length&&!confirm('Добавить демо-набор к существующим данным?'))return;const d=makeSeed();d.teams.forEach(t=>{if(!db.teams.some(x=>x.id===t.id))db.teams.push(t);});db.records.push(...d.records.filter(r=>!db.records.some(x=>x.id===r.id)));db.meta.demo=true;if(!db.draft.captain)db.draft.captain=d.teams[0]?.id;save();render();toast('Демо-набор восстановлен.');}}
function submit(e){const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const x=Object.fromEntries(new FormData(f).entries()),type=f.dataset.form;
if(type==='scout'){const t=team(x.teamId);if(!t){toast('Выбери команду.','error');return;}const r=newRecord({...x,autoLeave:f.elements.autoLeave.checked,autoPark:f.elements.autoPark.checked,teleopPark:f.elements.teleopPark.checked,disabled:f.elements.disabled.checked},t.id);db.records.push(r);db.meta.demo=false;save();toast('Наблюдение сохранено локально.');page='scouting';render();}
else if(type==='team'){const no=String(x.number||'').trim();if(db.teams.some(t=>t.number.toLowerCase()===no.toLowerCase())){toast('Такая команда уже есть.','error');return;}const t={id:no,number:no,name:String(x.name||'').trim(),region:String(x.region||'').trim(),style:String(x.style||'').trim(),notes:''};db.teams.push(t);if(!db.draft.captain)db.draft.captain=t.id;db.meta.demo=false;save();closeModal();activeTeam=null;renderTeams();toast('Команда добавлена.');}
else if(type==='settings'){db.meta.eventName=String(x.eventName||'').trim();db.meta.eventCode=String(x.eventCode||'').trim();db.meta.season=String(x.season||'2026-2027').trim();db.meta.demo=false;save();renderData();toast('Настройки турнира сохранены.');}}
document.addEventListener('click',click);document.addEventListener('submit',submit);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});render();
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
})();
